// scripts/build-signer.mjs from contracts/reference/intent-core.cjs + this file.
// Contract: contracts/intent.md, contracts/schemas/signer-{request,response}.schema.json.
// Logging policy: none. This file writes nothing to any log. Errors return a code only.

const { privateKeyToAccount } = require('viem/accounts');
const { getAddress } = require('viem');

const STATUS = {
  bad_request: 400, bad_mac: 401,
  rule_chain: 403, rule_asset: 403, rule_from: 403, rule_payto: 403, rule_amount: 403,
  rule_window: 403, rule_policy: 403, rule_audience: 403, stale_intent: 403,
  key_unavailable: 500, key_mismatch: 500, internal: 500,
};

function fail(code) {
  return { res: { statusCode: STATUS[code] || 500, body: { ok: false, code } } };
}

async function loadKey(event) {
  const opts = event.applicationOptions || {};
  const id = event.configuration && event.configuration.WALLET_TOKEN_ID;
  if (!opts.apiKey || !opts.baseUrl || !id) return null;
  const r = await fetch(`${opts.baseUrl}/tokens/${encodeURIComponent(id)}`, { headers: { 'BT-API-KEY': opts.apiKey } });
  if (!r.ok) return null;
  const tok = await r.json();
  const pk = tok && tok.data;
  return typeof pk === 'string' && /^0x[0-9a-fA-F]{64}$/.test(pk) ? pk : null;
}

module.exports = async function (event) {
  try {
    const cfg = (event && event.configuration) || {};
    const req = (event && event.req) || {};
    const intent = req.intent;
    if (!intent || typeof intent !== 'object' || typeof req.intent_mac !== 'string') return fail('bad_request');

    try { canonicalize(intent); } catch (e) { return fail('bad_request'); }          // exactly 14 string fields
    if (!cfg.INTENT_HMAC_KEY || !verifyMac(intent, req.intent_mac, cfg.INTENT_HMAC_KEY)) return fail('bad_mac');

    const nowSec = Math.floor(Date.now() / 1000);
    const rule = checkRules(intent, cfg, nowSec);
    if (rule) return fail(rule);

    const pk = await loadKey(event);
    if (!pk) return fail('key_unavailable');
    const account = privateKeyToAccount(pk);
    if (account.address.toLowerCase() !== String(cfg.WALLET_ADDRESS).toLowerCase()) return fail('key_mismatch');

    const signature = await account.signTypedData(typedDataFor(intent, cfg, getAddress));
    return { res: { statusCode: 200, body: { ok: true, from: account.address, signature, attempt_id: intent.attempt_id } } };
  } catch (e) {
    return fail('internal');
  }
};
